  overlay=doc.createElement('dialog');overlay.className='aemap-dialog';overlay.dataset.theme=doc.querySelector('#aelderan-unified-shell')?.dataset.theme||'dark';doc.body.appendChild(overlay);overlay.appendChild(root);root.classList.add('is-expanded');root.querySelector('[data-aemap-close]').hidden=false;root.querySelector('[data-aemap-action="expand"]').hidden=true;
