        if (r.includes('黑暗精灵') || r.includes('暗影精灵')) return SvgIcon('twemoji:elf-dark-skin-tone', s);
        if (r.includes('矮人') || r.includes('灰矮人')) return SvgIcon('twemoji:man-beard', s);
