        function getDiscardQuantityBounds() {
            const discardButton = $('#btn-confirm-discard');
            const maximum = Math.max(
                1,
                parseInt(discardButton.data('max-qty')) || 1
            );
            const input = $('#discard-qty-input');
            const current = Math.max(
                1,
                Math.min(maximum, parseInt(input.val()) || 1)
            );
            return { input, current, maximum };
        }

        function setDiscardQuantity(nextQuantity) {
            const { input, maximum } = getDiscardQuantityBounds();
            const next = Math.max(
                1,
                Math.min(maximum, parseInt(nextQuantity) || 1)
            );
            input.val(next);

            const atMinimum = next <= 1;
            const atMaximum = next >= maximum;
            $('.btn-discard-minus')
                .toggleClass('is-disabled', atMinimum)
                .attr('aria-disabled', String(atMinimum));
            $('.btn-discard-plus')
                .toggleClass('is-disabled', atMaximum)
                .attr('aria-disabled', String(atMaximum));
            return next;
        }

        $('body').on('click.aelderan', '.btn-discard-minus', function(e) {
            e.preventDefault();
            e.stopPropagation();
            const { current } = getDiscardQuantityBounds();
            setDiscardQuantity(current - 1);
        });

        $('body').on('click.aelderan', '.btn-discard-plus', function(e) {
            e.preventDefault();
            e.stopPropagation();
            const { current } = getDiscardQuantityBounds();
            setDiscardQuantity(current + 1);
        });

        $('body').on('click.aelderan', '#btn-discard-all', function(e) {
            e.preventDefault();
            e.stopPropagation();
            const { maximum } = getDiscardQuantityBounds();
            setDiscardQuantity(maximum);
        });

        $('body').on('keydown.aelderan', '.btn-discard-minus, .btn-discard-plus, #btn-discard-all', function(e) {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            e.preventDefault();
            $(this).trigger('click');
        });

        $('body').on('click.aelderan', '#btn-confirm-discard', async function() {
            const discardButton = $(this);

            if (discardButton.data('busy') === true) return;

            const itemName = discardButton.data('item-name');
            const requestedQty = Math.max(
                1,
                parseInt($('#discard-qty-input').val()) || 1
            );

            const modalMaxQty = Math.max(
                1,
                parseInt(discardButton.data('max-qty')) || 1
            );

            if (!itemName) return;

            const discardQty = Math.min(requestedQty, modalMaxQty);

            if (!confirm(`确定要丢弃 ${discardQty} 个 [${itemName}] 吗？`)) {
                return;
            }

            if (!beginAelderanMvuWrite('丢弃物品')) {
                return;
            }

            discardButton
                .data('busy', true)
                .css({
                    'pointer-events': 'none',
                    'opacity': '0.5'
                });

            try {
                const {
                    win,
                    msgId,
                    realData
                } = getLatestMvuWriteContext();

                if (
                    !realData ||
                    !realData.stat_data ||
                    !realData.stat_data['主角面板']
                ) {
                    alert("报错！未能读取到主角面板数据。");
                    return;
                }

                const panel = realData.stat_data['主角面板'];

                if (
                    !panel['物品栏'] ||
                    typeof panel['物品栏'] !== 'object'
                ) {
                    alert("报错！未能读取到物品栏数据。");
                    return;
                }

                const inv = panel['物品栏'];
                const itemData = inv[itemName];

                if (!itemData) {
                    alert("背包里已经没有这个物品了。");
                    return;
                }

                let actualOldQty = 1;

                if (typeof itemData === 'string') {
                    const parts = itemData
                        .split('|')
                        .map(part => part.trim());

                    actualOldQty = Math.max(
                        1,
                        parseInt(parts[0]) || 1
                    );

                    const actualDiscardQty = Math.min(
                        discardQty,
                        actualOldQty
                    );

                    const newQty = actualOldQty - actualDiscardQty;

                    if (newQty > 0) {
                        parts[0] = String(newQty);
                        inv[itemName] = parts.join(' | ');
                    } else {
                        delete inv[itemName];
                    }
                } else if (typeof itemData === 'object') {
                    actualOldQty = Math.max(
                        1,
                        parseInt(itemData['数量']) || 1
                    );

                    const actualDiscardQty = Math.min(
                        discardQty,
                        actualOldQty
                    );

                    const newQty = actualOldQty - actualDiscardQty;

                    if (newQty > 0) {
                        itemData['数量'] = newQty;
                    } else {
                        delete inv[itemName];
                    }
                } else {
                    alert("这个物品的数据格式无法识别。");
                    return;
                }

                const actualDiscardQty = Math.min(
                    discardQty,
                    actualOldQty
                );

                const weightPerItem = Math.max(
                    0,
                    Number(discardButton.data('weight')) || 0
                );

                const droppedWeight =
                    actualDiscardQty * weightPerItem;

                if (
                    !panel['负重'] ||
                    typeof panel['负重'] !== 'object'
                ) {
                    panel['负重'] = {
                        当前: 0,
                        上限: 10
                    };
                }

                panel['负重']['当前'] = Math.max(
                    0,
                    (Number(panel['负重']['当前']) || 0) -
                    droppedWeight
                );

                recalcHeroDerivedStats(panel);

                await commitLatestMvuWrite(
                    win,
                    realData,
                    msgId
                );

                $('#aelderan-item-modal').css(
                    'display',
                    'none'
                );
            } catch (error) {
                console.error('[丢弃物品]', error);
                alert("执行丢弃时出错了，可以查看控制台报错。");
            } finally {
                endAelderanMvuWrite();

                discardButton
                    .data('busy', false)
                    .css({
                        'pointer-events': 'auto',
                        'opacity': '1'
                    });
            }
        });

        content.on('click.aelderan', '.craft-material-remove', function(e) {
            e.stopPropagation();
            const index = $(this).data('index');
            if (index !== undefined && index >= 0 && index < craftMaterials.length) {
                craftMaterials.splice(index, 1);
                render();
            }
        });

        content.on('click.aelderan', '#aelderan-btn-craft-fire', function(e) {
            if (wrapper.data('isDragging')) return;
            if (craftMaterials.length === 0 && !craftConcept.trim() && !craftTarget.trim()) {
                alert("总得放点什么进去，或者写点你想造什么吧，哥哥...");
                return;
            }

            const sd = getMvuDataSafe();
            let matTypesCount = craftMaterials.length;
            let matTotalCount = craftMaterials.reduce((sum, item) => sum + item.qty, 0);
            let matString = craftMaterials.map(m => `[${m.name}]x${m.qty}`).join('、');
            if (!matString) matString = '无实体材料';

            let trimmedConcept = craftConcept.trim();
            let conceptStr = trimmedConcept ? "“" + trimmedConcept + "”" : "无";

            let trimmedTarget = craftTarget.trim();
            let targetStr = trimmedTarget ? "🎯 预期制造目标：*" + trimmedTarget + "*" : "🎯 预期制造目标：未指定具体形态";

            let locName = getVal(sd, '主角面板.当前位置.大区域.名称', '未知区域');
            let locSub = getVal(sd, '主角面板.当前位置.小区域', '');
            let fullLoc = locSub ? locName + " · " + locSub : locName;

            let tData = getVal(sd, '世界数据.世界时间', {});
            let preciseTimeStr = `${getVal(tData, '当前纪元', '未知纪元')} 第${Math.abs(Math.floor(getVal(tData, '年份', 1)))}年 第${Math.floor(getVal(tData, '天数', 1))}天 ${getVal(tData, '时钟', '--:--')}`;

            let lifeJob = getVal(sd, '主角面板.生活职业', '未知');
            let lifeSkillsObj = getVal(sd, '主角面板.生活技能', {});
            let lifeSkillStr = Object.entries(lifeSkillsObj).map(k => `${k[0]}(${getVal(k[1], '熟练度等级', '学徒')})`).join('、');
            if (!lifeSkillStr) lifeSkillStr = '无相关技能';

            let craftCommand = "【系统操作：战备-制造发起】\n" +
        "**投入实体材料**：" + matString + "（共" + matTypesCount + "种，" + matTotalCount + "件物品，请 DM 从物品栏扣除）。\n" +
        "**" + targetStr + "**\n" +
        "**注入概念/媒介**：*" + conceptStr + "*\n" +
        "**制造者能力底蕴**：生活职业-[" + lifeJob + "]，所持生活技能-[" + lifeSkillStr + "]。\n" +
        "**当前物理环境监测**：位置-[" + fullLoc + "]，天气-[(请DM依当前局势裁定)]，时间-[" + preciseTimeStr + "]。\n" +
        "**DM 裁决请求**：请 DM 首先根据上述【实体材料的核心材质】与【制造者能力底蕴】，自行决定本次制造所依赖的核心主属性及相关技能熟练度。随后，严格评估材料相性、注入概念的逻辑干涉，以及当前环境气候的影响。立即进行一次制造对抗检定。\n" +
        "**耗时与队列裁定**：请 DM 严格评估本次制造的工程量。若为简单拼凑或瞬间修补，请直接在正文结算并下发产物；若为耗时较长（数小时、数天甚至更久）的复杂工程，请不要立刻给予产物，而是根据当前时间（第X天 HH:MM）推算出一个确切的“预计完成时间”，并加入制造队列中。";

            sendSystemCommand(craftCommand);

            craftMaterials = [];
            craftConcept = "";
            craftTarget = "";
            render();
        });

        async function updatePlotToMvu(longText, shortText) {
            if (!beginAelderanMvuWrite('更新剧情')) {
                return false;
            }

            try {
                const {
                    win,
                    msgId,
                    realData
                } = getLatestMvuWriteContext();

                if (
                    !realData.stat_data['世界数据'] ||
                    typeof realData.stat_data['世界数据'] !== 'object'
                ) {
                    realData.stat_data['世界数据'] = {};
                }

                if (longText !== null) {
                    realData.stat_data['世界数据']['参考长线剧情'] =
                        longText;
                }

                if (shortText !== null) {
                    realData.stat_data['世界数据']['参考短线剧情'] =
                        shortText;
                }

                await commitLatestMvuWrite(
                    win,
                    realData,
                    msgId
                );

                return true;
            } catch (e) {
                console.warn('[剧情更新] 写入MVU失败:', e);
                alert(
                    `剧情数据同步失败：${
                        e && e.message ? e.message : e
                    }`
                );
                return false;
            } finally {
                endAelderanMvuWrite();
            }
        }

