    sectionRegistry,
    composePrompt,
    xmlParser,
    generateId,
    generateHistoryReference,
    generateCrossSectionSummary,
    normalizePosts,
    recordPostAssociation,
    repairForumPosts,
    mountSectionSchemeDocument,
