    root.调度[`必选${kind}`] = safeArray(root.调度[`必选${kind}`]).filter(item => item !== name);
    if (root.调度.人物关注设置[kind + ':' + name]) root.调度.人物关注设置[target + ':' + name] = root.调度.人物关注设置[kind + ':' + name];
