    const joint = CALL_MODULES.filter(item => !selected.has(item.id));
    const calls = CALL_MODULES.filter(item => selected.has(item.id) && item.id !== 'community')
      .map(item => ({ id: item.id, 名称: item.stage, 模块: [item.id] }));
