    const echoId = `${text(item.原帖ID)}-echo-${stableId(JSON.stringify([payload.世界时间, item.类型, item.内容, uniqueText(item.依据ID, 8).sort()]))}`;
    return !safeArray(existing.get(text(item.原帖ID))?.comments).some(comment => comment.id === echoId);
