    const blocked = action => {
      const kind = text(action?.类型), name = text(action?.名称);
      if (ACTOR_KINDS.includes(kind)) {
        if (!text(selectedObjectState(root, action).名称)) return !name || name === text(identity.名称);
        return focusBlockReason(root, kind, name, clock, identity);
      }
      return name === text(identity.名称) || !isSelectionDue(root, action, clock);
    };
