    const playerLimit = modules.actors ? actorAnalysisLimit(root) : Number(root.调度.重点玩家上限) || 0;
    const selectedNames = new Set(safeArray(director.选择对象).map(item => text(item.类型) + ':' + text(item.名称)));
    const allowed = action => selectedNames.has(text(action.类型) + ':' + text(action.名称)) && !blocked(action);
    const worldSide = { ...emptyWorldSideResult(), NPC行动: safeArray(npc.NPC行动).filter(allowed).slice(0, npcLimit),
      阵营势力行动: safeArray(org.阵营势力行动).filter(allowed),
      事件变化: unifiedRunHasModule(root, 'events') ? safeArray(events.事件变化).concat(safeArray(org.事件变化)) : [], 关系变化: [...safeArray(npc.关系变化), ...safeArray(org.关系变化)],
      可偶遇NPC: safeArray(npc.可偶遇NPC), 建议正式更新: [...safeArray(npc.建议正式更新), ...safeArray(org.建议正式更新)] };
    const playerSide = { 玩家行动: playersDue ? safeArray(players.玩家行动).filter(allowed).slice(0, playerLimit) : [],
      公会行动: safeArray(org.公会行动).filter(allowed),
      名册变化: [...(playersDue && playerLimit ? safeArray(players.名册变化) : []), ...safeArray(org.名册变化)],
      排行变动: playersDue && playerLimit ? safeArray(players.排行变动) : [], 公会成员变化: safeArray(org.公会成员变化),
      关系变化: safeArray(players.关系变化), 可偶遇玩家: safeArray(players.可偶遇玩家),
      建议正式更新: safeArray(players.建议正式更新) };
    const result = combineStageResults(director, worldSide, playerSide);
    if (modules.actors) {
      result.角色行动.push(...safeArray(actors.生物行动).filter(allowed));
      result.角色行动 = result.角色行动.slice(0, actorAnalysisLimit(root));
      result.关系变化 = [...safeArray(actors.关系变化), ...safeArray(org.关系变化)];
      result.建议正式更新 = [...safeArray(actors.建议正式更新), ...safeArray(org.建议正式更新)];
      const activeCreatures = new Set(result.角色行动.filter(item => item.类型 === '生物').map(item => item.名称));
      result.可偶遇对象.push(...safeArray(actors.可偶遇生物).filter(item => activeCreatures.has(item.名称)));
    }
    result.本轮摘要 = uniqueText(Object.values(modules).map(item => item?.本轮摘要), 4).join('；').slice(0, 600);
    result.世界变化 = environment.世界变化;
