    for(const el of doc.querySelectorAll('#aelderan-terminal-wrapper[data-aeu-world-scope="organizations"] :is(#tab-world-macro,#tab-world-guild) .scroll-capture>div:first-child'))for(const text of el.childNodes)if(text.nodeType===3){const value=text.nodeValue.trim(),labels={'【阵营动态】':'阵营记录','【势力动态】':'势力记录','【公会动态】':'公会记录'};if(Object.hasOwn(labels,value))rewrite(text,text.nodeValue.replace(value,labels[value]));}
